1	export type Severity = 'block' | 'warn';
2	
3	export interface GateCheck {
4	  id: string;
5	  title: string;
6	  /** Matches the subsection heading inside the Responsible AI Gate section. */
7	  headingPattern: RegExp;
8	  /** When true, a body without any digit produces a warning (thresholds expected). */
9	  expectsNumbers?: boolean;
10	}
11	
12	/** Matches both the branded "FRAI Gate" heading and the long-form "Responsible AI Gate". */
13	export const GATE_HEADING = /(responsible\s+ai|frai)\s+gate/i;
14	
15	export const RISK_TIERS = ['prohibited', 'high', 'limited', 'minimal'] as const;
16	export type RiskTier = (typeof RISK_TIERS)[number];
17	
18	export const GATE_CHECKS: GateCheck[] = [
19	  { id: 'risk-tier', title: 'Risk tier', headingPattern: /risk|tier/i },
20	  {
21	    id: 'data-privacy',
22	    title: 'Data & privacy',
23	    headingPattern: /data|privacy|provenance/i
24	  },
25	  { id: 'oversight', title: 'Human oversight', headingPattern: /oversight|human|control/i },
26	  {
27	    id: 'evaluation',
28	    title: 'Evaluation plan',
29	    headingPattern: /eval/i,
30	    expectsNumbers: true
31	  },
32	  { id: 'bias', title: 'Bias & fairness', headingPattern: /bias|fairness/i },
33	  {
34	    id: 'monitoring',
35	    title: 'Monitoring & rollback',
36	    headingPattern: /monitor|rollback/i,
37	    expectsNumbers: true
38	  },
39	  {
40	    id: 'transparency',
41	    title: 'Transparency & incidents',
42	    headingPattern: /transparen|incident|disclosure/i
43	  }
44	];
45	
46	export interface Finding {
47	  checkId: string;
48	  severity: Severity;
49	  message: string;
50	  /** 'validator' for deterministic findings, 'agent' for smart-review findings. */
51	  source: 'validator' | 'agent';
52	}
53	
54	export type Verdict = 'PASS' | 'WARN' | 'BLOCK';
55	
56	export interface GateResult {
57	  verdict: Verdict;
58	  tier: RiskTier | null;
59	  findings: Finding[];
60	  /** Raw text of the gate section, when found. */
61	  gateSection: string | null;
62	}
63	
64	export function verdictFrom(findings: Finding[]): Verdict {
65	  if (findings.some((f) => f.severity === 'block')) return 'BLOCK';
66	  if (findings.some((f) => f.severity === 'warn')) return 'WARN';
67	  return 'PASS';
68	}
