1	import {
2	  Finding,
3	  GATE_CHECKS,
4	  GATE_HEADING,
5	  GateResult,
6	  RISK_TIERS,
7	  RiskTier,
8	  verdictFrom
9	} from './schema.js';
10	
11	const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
12	/** A template field line whose value was never filled in, e.g. `- **Retention**:` */
13	const EMPTY_FIELD = /^\s*[-*]\s*\*\*[^*]+\*\*.*:\s*$/;
14	
15	interface Section {
16	  heading: string;
17	  body: string;
18	}
19	
20	function stripComments(markdown: string): string {
21	  return markdown.replace(/<!--[\s\S]*?-->/g, '');
22	}
23	
24	/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
25	export function extractGateSection(markdown: string): string | null {
26	  const lines = markdown.split(/\r?\n/);
27	  let start = -1;
28	  let level = 0;
29	  for (let i = 0; i < lines.length; i += 1) {
30	    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
31	    if (m && GATE_HEADING.test(m[2])) {
32	      start = i;
33	      level = m[1].length;
34	      break;
35	    }
36	  }
37	  if (start === -1) return null;
38	  let end = lines.length;
39	  for (let i = start + 1; i < lines.length; i += 1) {
40	    const m = lines[i].match(/^(#{1,6})\s+/);
41	    if (m && m[1].length <= level) {
42	      end = i;
43	      break;
44	    }
45	  }
46	  return lines.slice(start, end).join('\n');
47	}
48	
49	/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
50	function splitSubsections(gateSection: string): Section[] {
51	  const lines = gateSection.split(/\r?\n/);
52	  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
53	  const sections: Section[] = [];
54	  let current: Section | null = null;
55	  for (const line of lines.slice(1)) {
56	    const m = line.match(/^(#{1,6})\s+(.*)$/);
57	    if (m && m[1].length > gateLevel) {
58	      if (current) sections.push(current);
59	      current = { heading: m[2].trim(), body: '' };
60	    } else if (current) {
61	      current.body += `${line}\n`;
62	    }
63	  }
64	  if (current) sections.push(current);
65	  return sections;
66	}
67	
68	function extractTier(body: string): RiskTier | null {
69	  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
70	  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
71	  const fieldLine = body
72	    .split(/\r?\n/)
73	    .find((l) => /\*\*tier\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l));
74	  const haystacks = fieldLine ? [fieldLine] : [body];
75	  for (const text of haystacks) {
76	    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
77	    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
78	    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
79	    if (found.length === 1) return found[0];
80	    if (found.length > 1) {
81	      // Ambiguous mention; prefer the value after a colon on the field line.
82	      const afterColon = cleaned.split(':').slice(1).join(':');
83	      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
84	      if (inValue.length === 1) return inValue[0];
85	    }
86	  }
87	  return null;
88	}
89	
90	function answeredText(body: string): string {
91	  return body
92	    .split(/\r?\n/)
93	    .filter((l) => !EMPTY_FIELD.test(l))
94	    .join('\n')
95	    .trim();
96	}
97	
98	export function validateSpec(markdown: string): GateResult {
99	  const findings: Finding[] = [];
100	  const clean = stripComments(markdown);
101	  const gateSection = extractGateSection(clean);
102	
103	  if (!gateSection) {
104	    findings.push({
105	      checkId: 'structure',
106	      severity: 'block',
107	      message: 'No "## Responsible AI Gate" section found in the spec.',
108	      source: 'validator'
109	    });
110	    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
111	  }
112	
113	  const subsections = splitSubsections(gateSection);
114	  let tier: RiskTier | null = null;
115	
116	  for (const check of GATE_CHECKS) {
117	    const section = subsections.find((s) => check.headingPattern.test(s.heading));
118	    if (!section) {
119	      findings.push({
120	        checkId: check.id,
121	        severity: 'block',
122	        message: `Missing gate subsection: "${check.title}".`,
123	        source: 'validator'
124	      });
125	      continue;
126	    }
127	
128	    const body = section.body;
129	    const answered = answeredText(body);
130	
131	    if (!answered) {
132	      findings.push({
133	        checkId: check.id,
134	        severity: 'block',
135	        message: `"${check.title}" is present but empty.`,
136	        source: 'validator'
137	      });
138	      continue;
139	    }
140	    if (PLACEHOLDER.test(body)) {
141	      findings.push({
142	        checkId: check.id,
143	        severity: 'block',
144	        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
145	        source: 'validator'
146	      });
147	    }
148	    const emptyFields = body.split(/\r?\n/).filter((l) => EMPTY_FIELD.test(l));
149	    for (const line of emptyFields) {
150	      findings.push({
151	        checkId: check.id,
152	        severity: 'block',
153	        message: `Unanswered field in "${check.title}": ${line.trim()}`,
154	        source: 'validator'
155	      });
156	    }
157	    if (check.expectsNumbers && !/\d/.test(answered)) {
158	      findings.push({
159	        checkId: check.id,
160	        severity: 'warn',
161	        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
162	        source: 'validator'
163	      });
164	    }
165	
166	    if (check.id === 'risk-tier') {
167	      tier = extractTier(body);
168	      if (!tier) {
169	        findings.push({
170	          checkId: check.id,
171	          severity: 'block',
172	          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
173	          source: 'validator'
174	        });
175	      } else if (tier === 'prohibited') {
176	        findings.push({
177	          checkId: check.id,
178	          severity: 'block',
179	          message: 'Risk tier is "prohibited" - this feature must not be built.',
180	          source: 'validator'
181	        });
182	      } else if (tier === 'high') {
183	        const signoffLine = body
184	          .split(/\r?\n/)
185	          .find((l) => /sign[- ]?off/i.test(l) && !EMPTY_FIELD.test(l));
186	        const signoffValue = signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
187	        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
188	          findings.push({
189	            checkId: check.id,
190	            severity: 'block',
191	            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
192	            source: 'validator'
193	          });
194	        }
195	      }
196	    }
197	  }
198	
199	  return { verdict: verdictFrom(findings), tier, findings, gateSection };
200	}
201

